#!/bin/bash

# Use xml to extract all comments
xmls=$(find doc/xml -name "*.xml")

export misspell=0

for xml in $xmls
do
    # Sentences between <para> and </para> are generated by comments instead of code
    paras=$(grep -oP '(?<=<para>)[^<]+' $xml)
    echo "$paras" | while read -r para;
    do
        # Remove words with one or two characters in <para>
        para=$(echo "$para" | sed -E 's/\b[A-Za-z0-9_]{1,2}\b//g')
        # Split CamelCase words
        para=$(echo "$para" | sed -E 's/([a-z])([A-Z][a-z])/\1 \2/g')
        #  -L     Print lines with misspelled words.
        line=$(echo "$para" | hunspell -d en_US -L -p rtmotion_dictionary.txt)
        #  -l    Print the misspell word
        word=$(echo "$para" | hunspell -d en_US -l -p rtmotion_dictionary.txt | tr '\n' ' ')
        # -a      Print a oneline suggestion.
        suggestions=$(echo "$para" | hunspell -d en_US -a -p rtmotion_dictionary.txt | grep "^[\&#]")

        if [ -n "$word" ]; then
            echo "====================="
            echo "misspell in $xml"
            echo ""
            echo "Line containing misspelling: "
            echo "$line"
            echo ""
            echo "Wrong words: "
            echo "$word"
            echo ""
            echo "Suggestions: "
            echo "$suggestions"
            echo ""
            misspell=1
        fi
    done
done

if [ $misspell -ne 0 ]; then
    echo ""
    echo "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
    echo " Found spelling errors!"
    echo " If any of these misspelled words are false-positive,"
    echo " update the rtmotion_dictionary.txt file with the"
    echo " misspelled word to mark it as correct."
    echo ""
    echo " This version can't directly pointout where the "
    echo " misspelling lies in source code. You can use global" 
    echo " search to find the line."
    echo "!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!"
    echo ""
    exit 1
fi
